import importlib.util, pathlib, sys, time
p = pathlib.Path('problems/23/writeup/_codex_eq_odl1_rung2_face_split_quotient_probe.py').resolve()
sys.path.insert(0, str(p.parent))
spec = importlib.util.spec_from_file_location('qp', p)
qp = importlib.util.module_from_spec(spec); sys.modules['qp'] = qp; spec.loader.exec_module(qp)
print('loaded', flush=True)
t=time.monotonic(); chart = qp.charts.build_chart(9); print('chart', time.monotonic()-t, flush=True)
t=time.monotonic(); target = qp.homogenize_poly(chart.target, chart.variables, qp.TARGET_DEGREE); print('target_hom', len(target), time.monotonic()-t, flush=True)
t=time.monotonic(); gen_polys = [qp.homogenize_poly(expr, chart.variables, qp.GEN_DEGREE) for expr in chart.generators]; print('gen_hom', time.monotonic()-t, flush=True)
divisor, _, _ = qp.monic_normalize(gen_polys[7])
t=time.monotonic(); quo_p, rem_p = qp.divide_grevlex(target, divisor); print('target_divide', len(rem_p), len(quo_p), time.monotonic()-t, flush=True)
exps = qp.base_candidate_exps(side='face', degree=qp.TARGET_DEGREE, divisor=divisor, rem_support=set(rem_p), quo_support=set(quo_p), support_mode='all', num_vars=len(chart.variables))
print('candidates', len(exps), 'first', exps[0], flush=True)
t=time.monotonic(); col=qp.qcolumn(side='face', kind='face_base', name='B11', multiplier_exp=exps[0], poly=qp.bernstein_basis_poly(qp.TARGET_DEGREE, exps[0]), divisor=divisor); print('one_col', time.monotonic()-t, 'rem', len(col.rem), 'quo', len(col.quo), flush=True)
